import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    words = input_data[1:]

    # Use a set for O(1) average time complexity lookups
    word_set = set(words)
    typos = []

    for word in words:
        is_typo = False
        word_len = len(word)
        # If the word is empty or length 1, deleting a char results in empty string
        # Empty string is not in the dictionary (words consist of lowercase letters, unique, and typically non-empty in such problems)
        # But strictly following the rule: if deleting a char produces a word in the dictionary.
        # An empty string is unlikely to be in the dictionary based on problem description ("lowercase English letters"),
        # but let's handle it safely. If ' ' (empty) is not in word_set, then single char words cannot be typos.
        if word_len <= 1:
            is_typo = False
        else:
            # Generate all possible words by deleting one character
            seen_deletions = set()
            for i in range(word_len):
                # Create the new word by slicing
                new_word = word[:i] + word[i+1:]
                if new_word in word_set:
                    is_typo = True
                    break
                # Optimization: if we already found this new_word, no need to check again
                if new_word in seen_deletions:
                    continue
                seen_deletions.add(new_word)

        if is_typo:
            typos.append(word)

    if not typos:
        print("NO TYPOS")
    else:
        for t in typos:
            print(t)

