        # Optimization: if the word length is 1, deleting a char results in empty string.
        # Since all words consist of lowercase English letters and are unique, 
        # and typically dictionaries don't contain empty strings based on problem context ("words"),
        # we assume empty string is not in the dictionary. If it were, length 1 words would be typos.
        # However, standard interpretation implies non-empty words. Let's stick to generating substrings.

        if length > 0:
            for i in range(length):
                # Create the string with the i-th character removed
                candidate = word[:i] + word[i+1:]
                if candidate in word_set:
                    is_typo = True
                    break

        if is_typo:
            typos.append(word)

    if not typos:
        print("NO TYPOS")
